def test_every_exported_type_builds(name: str) -> None:
    """Models are built lazily, so a broken annotation would otherwise surface only at first use."""
    exported: Any = getattr(types, name)
    if inspect.ismodule(exported):
        return
    if inspect.isclass(exported) and issubclass(exported, pydantic.BaseModel):
        assert exported.model_rebuild(force=True) is not False
        assert issubclass(exported, tungoai.BaseModel)
    else:
        pydantic.TypeAdapter[Any](exported)


