def test_a_response_is_built_leniently() -> None:
    sent = fixture("listCompanyProposals")
    first = {**sent["data"][0], "title": None, "total": {**sent["data"][0]["total"], "amount_tiyn": "seven"}}
    body = {**sent, "data": [first, sent["data"][0]], "total": "many", "added_later": {"x": 1}}
    page: ProposalPage = build(ProposalPage, body)
    assert isinstance(page, ProposalPage)
    drifted, sound = page.data
    assert type(drifted) is type(sound), "an item that does not match is still its model"
    assert type(drifted.total) is type(sound.total), "and so is a model nested in it"
    assert type(drifted.approval) is type(sound.approval)
    loose: Any = drifted
    assert (loose.title, loose.total.amount_tiyn) == (None, "seven")
    assert sound.total.amount_tiyn == sent["data"][0]["total"]["amount_tiyn"]
    assert page.model_extra == {"added_later": {"x": 1}}
    assert "next_cursor" in page.model_fields_set
    assert page.to_dict() == body
    assert json.loads(page.to_json()) == body


