def test_money_is_exact() -> None:
    huge = 9_007_199_254_740_993  # 2**53 + 1: does not survive a float
    money = validate_as(Money, {"amount": 90071992547409.93, "amount_tiyn": huge, "formatted": "…"})
    assert money.amount_tiyn == huge
    assert isinstance(money.amount_tiyn, int)
    assert json.loads(money.to_json())["amount_tiyn"] == huge
    whole = validate_as(Money, {"amount": 1234, "amount_tiyn": 123400, "formatted": "1 234,00 ₸"})
    assert isinstance(whole.amount, int), "an integral JSON number is not turned into a float"


